    patterns = {}
    for i in range(len(data) - length + 1):
        pattern = data[i:i+length]
        if pattern in patterns:
            patterns[pattern].append(i)
        else:
            patterns[pattern] = [i]
    return {k: v for k, v in patterns.items() if len(v) > 1}

