#!/usr/bin/env python3

def to_num(s):
    x = 0
    for i in range(len(s)): x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def encr_vals(m_chr, k_chr, n):
    return (m_chr + k_chr) & ((1 << n) - 1)

def decrypt_vals(c_chr, k_chr, n):
    mask = (1 << n) - 1
    return (c_chr - k_chr) & mask

def decrypt(k_vals, c_vals, n):
    m_vals = []
    for i in range(len(c_vals)):
        k_idx = i % len(k_vals)
        m_val = decrypt_vals(c_vals[i], k_vals[k_idx], n)
        m_vals.append(m_val)
    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

def recover_key(known_text, ciphertext, n):
    # Convert known plaintext to values
    m_val_list = [get_vals(x, n) for x in get_nums(known_text, n)]
    m_vals = []
    for lst in m_val_list:
        m_vals += lst

    # Convert ciphertext to values
    c_val_list = [get_vals(x, n) for x in get_nums(ciphertext[:len(known_text)], n)]
    c_vals = []
    for lst in c_val_list:
        c_vals += lst

    # Recover key values
    k_vals = []
    mask = (1 << n) - 1
    for i in range(len(m_vals)):
        k_val = (c_vals[i] - m_vals[i]) & mask
        k_vals.append(k_val)

    return k_vals

def main():
    # Read ciphertext
    with open("ctf_files/ciphertext", "r") as f:
        ciphertext = f.read().strip()

    known_text = "flag{"

    print(f"Testing with known plaintext: {known_text}")

    for n in [2, 3]:
        print(f"\nTrying n={n}:")
        k_vals = recover_key(known_text, ciphertext, n)

        # Try different key lengths
        for key_len in range(1, len(k_vals) + 1):
            potential_key = k_vals[:key_len]

            # Convert ciphertext to values for decryption
            c_val_list = [get_vals(x, n) for x in get_nums(ciphertext, n)]
            c_vals = []
            for lst in c_val_list:
                c_vals += lst

            # Decrypt with potential key
            decrypted = decrypt(potential_key, c_vals, n)

            # If the decrypted text starts with our known text, it's promising
            if decrypted.startswith("flag{"):
                print(f"\nPotential key found (length {key_len}):")
                print(f"Key values: {potential_key}")
                print(f"Decrypted (first 20 chars): {decrypted[:20]}")

if __name__ == "__main__":
    main()

