#!/usr/bin/env python3
import string
from itertools import product

def to_num(s):
    x = 0
    for i in range(len(s)): x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def decr_vals(c_chr, k_chr, n):
    mask = (1 << n) - 1
    return (c_chr - k_chr) & mask

def decrypt(k, c, n):
    if (n >= 8): raise ValueError("n is too high!")
    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]

    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list: c_vals += lst
    for lst in k_val_list: k_vals += lst

    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n)
        for i in range(0, len(c_vals))]

    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

def is_printable_ascii(text):
    return all(32 <= ord(c) <= 126 for c in text)

def try_decrypt(ciphertext, key, n):
    try:
        decrypted = decrypt(key, ciphertext, n)
        is_printable = is_printable_ascii(decrypted)

        if is_printable and decrypted.isprintable():
            print(f"\nKey pattern: {key}")
            print(f"First 20 chars: {decrypted[:20]}")
            print(f"Valid ASCII only: {is_printable}")
            if len(decrypted) > 20:
                print(f"Next 20 chars: {decrypted[20:40]}")
            if "flag{" in decrypted.lower():
                print("!!! FLAG FOUND !!!")
                print("Full decrypted text:")
                print(decrypted)
                return True, decrypted

            # Look for meaningful text patterns
            common_words = ["the", "and", "ing", "flag", "ctf", "challenge"]
            for word in common_words:
                if word in decrypted.lower():
                    print(f"Found word: {word}")
                    print("Full decrypted text:")
                    print(decrypted)
                    return True, decrypted

        return False, None

    except Exception as e:
        return False, None

def main():
    # Read ciphertext
    with open('/home/ctfplayer/ctf_files/ciphertext', 'r') as f:
        hex_text = ''.join(f.read().strip().split('\n'))

    # Convert hex to bytes
    ciphertext = bytes.fromhex(hex_text).decode('latin1')

    n = 3  # Using n=3 as specified

    # Common CTF key patterns
    key_patterns = [
        "key", "xyz", "abc", "ctf", "pwn", "the", "and",
        "sec", "top", "rev", "bin", "hex", "cry", "bug",
        "win", "get", "box", "try", "yes", "now", "fix"
    ]

    # Try common key patterns with various repetitions
    print("Testing common key patterns...")
    for base_key in key_patterns:
        # Try the base key
        found, decrypted = try_decrypt(ciphertext, base_key, n)
        if found:
            return

        # Try repeated patterns
        for repeat in range(2, 5):
            key = base_key * repeat
            found, decrypted = try_decrypt(ciphertext, key, n)
            if found:
                return

    # Advanced pattern: Try common ASCII values
    print("\nTrying common ASCII value patterns...")
    ascii_ranges = [
        range(65, 91),  # Uppercase
        range(97, 123),  # Lowercase
        range(48, 58)   # Numbers
    ]

    # Try 3-character combinations from each range
    for ascii_range in ascii_ranges:
        for chars in product(ascii_range, repeat=3):
            key = ''.join(chr(c) for c in chars)
            found, decrypted = try_decrypt(ciphertext, key, n)
            if found:
                return

if __name__ == "__main__":
    main()

