#!/usr/bin/env python3
from binascii import unhexlify

def to_num(s):
    x = 0
    for i in range(len(s)):
        x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    if not val_list:
        return ""
    x = val_list[0]
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    chrs = []
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def decrypt_vals(c_chr, k_chr, n):
    mask = (1 << n) - 1
    return (c_chr - k_chr) & mask

def decrypt(ciphertext, key, n=3):
    c_nums = get_nums(ciphertext, n)
    k_nums = get_nums(key * ((len(ciphertext) // len(key)) + 1), n)

    c_vals = []
    k_vals = []

    for num in c_nums:
        c_vals.extend(get_vals(num, n))
    for num in k_nums:
        k_vals.extend(get_vals(num, n))

    k_vals = k_vals[:len(c_vals)]  # Trim key vals to match ciphertext length

    m_vals = [decrypt_vals(c_vals[i], k_vals[i], n) for i in range(len(c_vals))]
    m_chunks = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]

    return "".join(get_chrs(chunk, n) for chunk in m_chunks if chunk)

def main():
    # Read ciphertext
    with open('/home/ctfplayer/ctf_files/ciphertext', 'r') as f:
        hex_data = ''.join(line.strip() for line in f)
    ciphertext = unhexlify(hex_data).decode('latin1')

    n = 3  # We know n=3 from the challenge

    print(f"Testing decryption with n={n}...")

    # Create all possible 3-byte keys with values 0-7 (since n=3, max value is 7)
    for i in range(8):
        for j in range(8):
            for k in range(8):
                key = chr(i) + chr(j) + chr(k)
                try:
                    plaintext = decrypt(ciphertext, key, n)
                    # Check if the result contains printable ASCII and looks like a flag
                    if "flag{" in plaintext and all(32 <= ord(c) <= 126 for c in plaintext):
                        print(f"\nFound potential match!")
                        print(f"Key: {[ord(c) for c in key]}")
                        print(f"Plaintext: {plaintext}")
                        if "}" in plaintext:  # If we have a complete flag
                            return
                except Exception as e:
                    continue

if __name__ == "__main__":
    main()
